// Charts for this page. Data comes from data.js, generated by scripts/site_assets.py.
(function () {
  const D = window.SITE_DATA;
  const pct = v => Math.round(v * 100);
  const nice = s => s.replace('_', ' ').replace(/^\w/, c => c.toUpperCase());

  Charts.define('scorecard', (el, C) => {
    const labels = el.clientWidth < 520
      ? ['Pass', 'Tools', 'Args', 'Grounded']
      : ['Pass rate', 'Right tools', 'Right arguments', 'Grounded'];
    const keys = ['pass', 'tools', 'args', 'grounded'];
    const runs = D.evals.runs;
    const trace = (run, color) => ({
      type: 'bar', name: run.label, x: labels, y: keys.map(k => pct(run.metrics[k])),
      marker: { color, line: { width: 0 } }, text: keys.map(k => pct(run.metrics[k]) + '%'),
      textposition: 'outside', textfont: { color: C.ink, size: 12 }, cliponaxis: false,
      hovertemplate: '%{x}: %{y}%<extra>' + run.label + '</extra>',
    });
    return {
      data: [trace(runs.baseline, C.violet), trace({ ...runs.prompt_rules, label: 'Prompt experiment' }, C.grey)],
      layout: { yaxis: { range: [0, 112], ticksuffix: '%', dtick: 25 }, legend: { y: -0.16 }, margin: { t: 18 }, xaxis: { tickangle: 0 } },
    };
  });

  Charts.define('categories', (el, C) => {
    const rows = D.evals.by_category;
    const rate = rows.map(r => r.passed / r.total);
    return {
      data: [{
        type: 'bar', orientation: 'h', y: rows.map(r => nice(r.category)), x: rate.map(pct),
        text: rows.map(r => `${r.passed}/${r.total}`), textposition: 'outside', cliponaxis: false,
        textfont: { color: C.ink },
        marker: { color: rate.map(v => (v === 1 ? C.green : v === 0 ? C.rose : C.amber)) },
        hovertemplate: '%{y}: %{x}% passed<extra></extra>',
      }],
      layout: { xaxis: { range: [0, 118], ticksuffix: '%', dtick: 25 }, yaxis: { autorange: 'reversed' }, showlegend: false },
    };
  });

  Charts.define('composition', (el, C) => {
    const rows = D.evals.composition;
    const y = rows.map(r => nice(r.category));
    return {
      data: [
        { type: 'bar', orientation: 'h', name: 'Smoke set', y, x: rows.map(r => r.smoke), marker: { color: C.violet } },
        { type: 'bar', orientation: 'h', name: 'Nightly only', y, x: rows.map(r => r.full_only), marker: { color: C.violetDim } },
      ],
      layout: { barmode: 'stack', yaxis: { autorange: 'reversed' }, xaxis: { title: { text: 'questions' }, dtick: 2 }, legend: { y: -0.22 } },
    };
  });

  Charts.define('market', (el, C) => {
    const palette = { diesel: C.cyan, electric: C.green, hybrid: C.amber, petrol: C.violet };
    const data = Object.entries(D.market).map(([fuel, pts]) => ({
      type: 'scatter', mode: 'lines+markers', name: nice(fuel),
      x: pts.map(p => p.age), y: pts.map(p => p.median),
      line: { color: palette[fuel] || C.grey, width: 2.4, shape: 'spline' }, marker: { size: 5 },
      customdata: pts.map(p => p.n),
      hovertemplate: nice(fuel) + ', %{x} years: €%{y:,.0f} (n=%{customdata})<extra></extra>',
    }));
    return {
      data,
      layout: {
        xaxis: { title: { text: 'vehicle age (years)' }, dtick: 2 },
        yaxis: { title: { text: 'median price' }, tickprefix: '€', separatethousands: true },
        legend: { y: -0.24 }, hovermode: 'closest',
      },
    };
  });
})();
